# Verify that extended GTFS times (beyond 24:00:00) are preserved
import csv
with open('outputs/t05_clean_stop_times.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row['arrival_time'] >= '24:00:00' or row['departure_time'] >= '24:00:00':
            print(f'Extended time preserved: trip_id={row[\"trip_id\"]}, arrival={row[\"arrival_time\"]}, departure={row[\"departure_time\"]}')
""}
